questions.modelAnswer:
class ThreadSafeCache {
public:
  std::optional<std::string> get(int key) const {
    std::shared_lock lk(mu_);          // many readers in parallel
    auto it = map_.find(key);
    if (it == map_.end()) return std::nullopt;
    return it->second;                 // copy made while lock is held
  }
  void put(int key, std::string value) {
    std::unique_lock lk(mu_);          // exclusive writer
    map_.insert_or_assign(key, std::move(value));
  }
private:
  mutable std::shared_mutex mu_;       // mutable: locked in const get()
  std::unordered_map<int, std::string> map_;
};

