questions.modelAnswer:
#include <condition_variable>
#include <mutex>

// Writer-preferring reader-writer lock: once a writer waits, new readers wait too.
class RWLock {
  std::mutex m_;
  std::condition_variable cv_;
  int readers_ = 0;          // active readers
  int writers_waiting_ = 0;  // writers blocked in lock()
  bool writer_ = false;      // a writer holds the lock
public:
  void lock_shared() {
    std::unique_lock lk(m_);
    cv_.wait(lk, [this] { return !writer_ && writers_waiting_ == 0; });
    ++readers_;
  }
  void unlock_shared() {
    std::lock_guard lk(m_);
    if (--readers_ == 0) cv_.notify_all();   // a writer may be waiting
  }
  void lock() {
    std::unique_lock lk(m_);
    ++writers_waiting_;
    cv_.wait(lk, [this] { return !writer_ && readers_ == 0; });
    --writers_waiting_;
    writer_ = true;
  }
  void unlock() {
    std::lock_guard lk(m_);
    writer_ = false;
    cv_.notify_all();                         // wake all readers, or the next writer
  }
};

